ALTER TABLE public.job_sheets ADD COLUMN unlisted_equipment text;
CREATE OR REPLACE FUNCTION public.save_sheet_snapshot_with_photos(_id uuid,_expected timestamptz,_form jsonb,_logs jsonb,_parts jsonb) RETURNS timestamptz LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE stamp timestamptz; BEGIN PERFORM public.save_sheet_snapshot(_id,_expected,_form,_logs,_parts); UPDATE public.job_sheets SET photo_paths=coalesce(_form->'photo_paths',photo_paths),unlisted_equipment=CASE WHEN _form ? 'unlisted_equipment' THEN nullif(trim(_form->>'unlisted_equipment'),'') ELSE unlisted_equipment END WHERE id=_id RETURNING updated_at INTO stamp;RETURN stamp;END $$;
CREATE OR REPLACE FUNCTION public.guard_field_equipment_review() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
IF length(coalesce(NEW.unlisted_equipment,''))>500 THEN RAISE EXCEPTION 'Equipment details must be under 500 characters';END IF;
IF TG_OP='UPDATE' AND (NEW.lift_model,NEW.serial_number,NEW.unlisted_equipment) IS DISTINCT FROM(OLD.lift_model,OLD.serial_number,OLD.unlisted_equipment) AND public.my_role() NOT IN('admin','superuser') THEN NEW.requires_admin_approval=true;ELSIF TG_OP='UPDATE' AND OLD.requires_admin_approval AND NOT NEW.requires_admin_approval AND public.my_role() NOT IN('admin','superuser') THEN RAISE EXCEPTION 'Office review required to update the catalogue';END IF;RETURN NEW;END $$;
CREATE TRIGGER field_equipment_review BEFORE INSERT OR UPDATE ON public.job_sheets FOR EACH ROW EXECUTE FUNCTION public.guard_field_equipment_review();
CREATE POLICY field_sheet_history_limit ON public.job_sheets AS RESTRICTIVE FOR SELECT TO authenticated USING(company_id=public.current_company_id() AND (public.my_role() IN('admin','superuser') OR status<>'completed' OR created_at>=now()-make_interval(months=>coalesce((SELECT field_sheet_history_months FROM public.company_settings WHERE company_id=public.current_company_id()),12))));